import "aos/dist/aos.css";
import { FaTrademark } from "react-icons/fa";

export default function Trademark() {
    const registrationTypes = [
        "Indonesian Individual (WNI)",
        "Foreign Individual (WNA)",
        "Domestic Company (PMDN)",
        "Foreign Investment Company (PMA) in Indonesia",
        "Foreign Company (Overseas)",
    ];

    const scope = [
        "Trademark search & analysis",
        "Class determination (45 classes of goods & services)",
        "Submission of application to DGIP",
        "Official submission receipt from DGIP",
        "Free 1x opposition rebuttal",
    ];

    const timeline = [
        "Trademark Search & Analysis – 1 Working Day",
        "Power of Attorney Preparation – 1 Working Day",
        "Application Submission – 1 Working Day",
        "Submission Receipt – 1 Working Day",
    ];

    const requirements = [
        {
            title: "Indonesian Individual (WNI)",
            items: ["ID Card (KTP)", "Logo & Brand Name", "Active Email"],
        },
        {
            title: "Foreign Individual (WNA)",
            items: ["Passport", "Home Country ID", "Logo & Brand Name", "Active Email"],
        },
        {
            title: "Domestic Company (PMDN)",
            items: [
                "Deed of Establishment & Amendments",
                "Business Identification Number (NIB) & Ministry Approval (Kemenkumham)",
                "Company Tax ID (NPWP)",
                "Director’s ID Card",
                "Logo & Brand Name",
                "Active Email",
            ],
        },
        {
            title: "Foreign Investment Company (PMA)",
            items: [
                "Deed of Establishment & Amendments",
                "Business Identification Number (NIB) & Ministry Approval (Kemenkumham)",
                "Company Tax ID (NPWP)",
                "Director’s Passport",
                "KITAS/KITAP (if applicable)",
                "Logo & Brand Name",
                "Active Email",
            ],
        },
        {
            title: "Foreign Company",
            items: [
                "Company Deed",
                "Business License from Country of Origin",
                "Director’s Passport",
                "Logo & Brand Name",
                "Active Email",
            ],
        },
    ];

    return (
        <div className="pt-20">

            {/* HERO STYLE SECTION */}
            <section className="mb-24 bg-white">
                <div className="w-11/12 md:w-8/12 mx-auto text-center">

                    {/* ICON */}
                    <div
                        className="flex justify-center mb-6"
                        data-aos="zoom-in"
                    >
                        <div className="w-20 h-20 rounded-full bg-sky-100 flex items-center justify-center">
                            <FaTrademark className="text-sky-700 text-4xl" />
                        </div>
                    </div>

                    {/* TITLE */}
                    <h1
                        data-aos="fade-up"
                        className="text-3xl md:text-5xl font-bold text-sky-900 mb-6"
                    >
                        Trademark Registration
                    </h1>

                    <p
                        data-aos="fade-up"
                        data-aos-delay="200"
                        className="text-gray-600 max-w-2xl mx-auto mb-16"
                    >
                        Protect your business identity and reputation through
                        official trademark registration with the Directorate
                        General of Intellectual Property (DGIP).
                    </p>

                    {/* REGISTRATION TYPES */}
                    <div className="mb-24">
                        <h2
                            data-aos="fade-up"
                            className="text-2xl font-semibold text-sky-900 mb-8"
                        >
                            Registration Types
                        </h2>

                        <div className="grid grid-cols-1 sm:grid-cols-2 gap-8 text-left">
                            {registrationTypes.map((item, index) => (
                                <div
                                    key={index}
                                    data-aos="fade-up"
                                    data-aos-delay={index * 100}
                                    className="bg-white rounded-xl border border-gray-200 p-6 
                                    transition-all duration-300 ease-in-out
                                    hover:shadow-xl hover:scale-105"
                                >
                                    <p className="font-semibold text-sky-900">
                                        {item}
                                    </p>
                                </div>
                            ))}
                        </div>
                    </div>

                    {/* SCOPE OF WORK */}
                    <div className="mb-24">
                        <h2
                            data-aos="fade-up"
                            className="text-2xl font-semibold text-sky-900 mb-8"
                        >
                            Scope of Work
                        </h2>

                        <div className="grid sm:grid-cols-2 gap-6 text-left">
                            {scope.map((item, index) => (
                                <div
                                    key={index}
                                    data-aos="fade-up"
                                    data-aos-delay={index * 100}
                                    className="bg-sky-50 rounded-xl p-6 
                                    transition-all duration-300 hover:shadow-lg hover:scale-105"
                                >
                                    <p className="text-gray-700">
                                        {item}
                                    </p>
                                </div>
                            ))}
                        </div>
                    </div>

                    {/* TIMELINE */}
                    <div className="mb-28">
                        <h2
                            data-aos="fade-up"
                            className="text-2xl font-semibold text-sky-900 mb-16 text-center"
                        >
                            Processing Timeline (Initial Stage)
                        </h2>

                        <div className="relative max-w-4xl mx-auto">

                            {/* Vertical Line */}
                            <div className="absolute left-4 md:left-1/2 top-0 bottom-0 w-px bg-gray-200"></div>

                            {timeline.map((item, index) => (
                                <div
                                    key={index}
                                    data-aos="fade-up"
                                    data-aos-delay={index * 100}
                                    className={`relative mb-16 flex flex-col md:flex-row items-start md:items-center ${index % 2 === 0 ? "md:justify-start" : "md:justify-end"}`}
                                >

                                    {/* STEP NUMBER */}
                                    <div className="absolute left-0 md:left-1/2 transform md:-translate-x-1/2  w-10 h-10 rounded-full bg-sky-600 text-white  flex items-center justify-center text-sm font-semibold shadow-md">
                                        {(index + 1).toString().padStart(2, "0")}
                                    </div>

                                    {/* CONTENT CARD */}
                                    <div
                                        className={`mt-14 md:mt-0 md:w-[45%] w-full  bg-sky-600 text-white rounded-2xl p-6 shadow-sm  transition-all duration-300 hover:shadow-xl hover:-translate-y-1`}
                                    >
                                        <p className="text-white leading-relaxed text-sm md:text-base">
                                            {item}
                                        </p>
                                    </div>
                                </div>
                            ))}
                        </div>
                    </div>

                    {/* DOCUMENT REQUIREMENTS */}
                    <div>
                        <h2
                            data-aos="fade-up"
                            className="text-2xl font-semibold text-sky-900 mb-10"
                        >
                            Document Requirements
                        </h2>

                        <div className="grid grid-cols-1 sm:grid-cols-2 gap-8 text-left">
                            {requirements.map((req, index) => (
                                <div
                                    key={index}
                                    data-aos="fade-up"
                                    data-aos-delay={index * 100}
                                    className="bg-white rounded-xl border border-gray-200 p-6 
                                    transition-all duration-300 ease-in-out
                                    hover:shadow-xl hover:scale-105"
                                >
                                    <h4 className="font-semibold text-sky-900 mb-4">
                                        {req.title}
                                    </h4>

                                    <ul className="space-y-2">
                                        {req.items.map((item, i) => (
                                            <li
                                                key={i}
                                                className="flex gap-2 text-gray-600"
                                            >
                                                <span className="text-sky-600 font-bold">
                                                    •
                                                </span>
                                                {item}
                                            </li>
                                        ))}
                                    </ul>
                                </div>
                            ))}
                        </div>
                    </div>

                </div>
            </section>
        </div>
    );
}